import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import CryptoJS from 'crypto-js';

const useMarvelApi = (query) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const publicKey = process.env.REACT_APP_MARVEL_PUBLIC_KEY;
      const privateKey = process.env.REACT_APP_MARVEL_PRIVATE_KEY;
      const ts = new Date().getTime();
      const hash = CryptoJS.MD5(ts + privateKey + publicKey).toString();

      const baseURL = `https://gateway.marvel.com:443/v1/public/characters`;
      const response = await axios.get(baseURL, {
        params: {
          apikey: publicKey,
          ts,
          hash,
          nameStartsWith: query,
          offset,
          limit: 20,
        },
      });

      setData(prev => [...prev, ...response.data.data.results]);
      setOffset(prev => prev + response.data.data.count);
      setHasMore(response.data.data.total > offset + response.data.data.count);
    } catch (error) {
      setError(error);
    } finally {
      setLoading(false);
    }
  }, [query, offset]);

  useEffect(() => {
    setData([]);
    setOffset(0);
    setHasMore(true);
    if (query) fetchData();
  }, [query, fetchData]);

  return { data, loading, error, hasMore, fetchData };
};
